package android.widget;
public class Scroller { private int startX,startY,finalX,finalY,currX,currY,duration; private long startTime; private boolean finished=true; private android.view.animation.Interpolator interpolator; public Scroller(android.content.Context c) { this(c,null); } public Scroller(android.content.Context c,android.view.animation.Interpolator i) { interpolator=i; } public Scroller(android.content.Context c,android.view.animation.Interpolator i,boolean flywheel) { this(c,i); } public void startScroll(int sx,int sy,int dx,int dy) { startScroll(sx,sy,dx,dy,250); } public void startScroll(int sx,int sy,int dx,int dy,int d) { startX=currX=sx; startY=currY=sy; finalX=sx+dx; finalY=sy+dy; duration=Math.max(1,d); startTime=android.os.SystemClock.uptimeMillis(); finished=false; } public void fling(int sx,int sy,int vx,int vy,int minX,int maxX,int minY,int maxY) { int x=Math.max(minX,Math.min(maxX,sx+vx/2)); int y=Math.max(minY,Math.min(maxY,sy+vy/2)); startScroll(sx,sy,x-sx,y-sy,500); } public boolean computeScrollOffset() { if(finished) return false; float t=(float)(android.os.SystemClock.uptimeMillis()-startTime)/duration; if(t>=1) { currX=finalX; currY=finalY; finished=true; } else { float v=interpolator==null?viscous(t):interpolator.getInterpolation(t); currX=startX+Math.round((finalX-startX)*v); currY=startY+Math.round((finalY-startY)*v); } return true; } private float viscous(float x) { x*=8; if(x<1) x-=1-(float)Math.exp(-x); else x=1-(float)Math.exp(1-x)*.36787945f; return x*1.0005769f; } public boolean isFinished() { return finished; } public void forceFinished(boolean f) { finished=f; } public void abortAnimation() { currX=finalX; currY=finalY; finished=true; } public int getCurrX() { return currX; } public int getCurrY() { return currY; } public int getStartX() { return startX; } public int getStartY() { return startY; } public int getFinalX() { return finalX; } public int getFinalY() { return finalY; } public int getDuration() { return duration; } public void setFinalX(int x) { finalX=x; finished=false; } public void setFinalY(int y) { finalY=y; finished=false; } public float getCurrVelocity() { return 0; } }
